import {reportUsd} from '@/lib/report-export';
import {serviceComponents,type ServiceTotals} from '@/lib/service-days';
export function ServiceTotalsView({totals}:{totals:ServiceTotals}){return <div className="pilot-report-totals">{[...serviceComponents,['revenue_minor','Revenue subtotal'],['total_minor','Total allocation'],['occupied_nights','Occupied nights']].map(([key,label])=><div key={key}><span>{label}</span><strong>{key==='occupied_nights'?totals.occupied_nights:reportUsd(totals[key as keyof ServiceTotals] as number)}</strong></div>)}</div>}
export function ServiceTotalsBreakdown({ordinary,corrections,total}:{ordinary:ServiceTotals;corrections:ServiceTotals;total:ServiceTotals}){return <div className="pilot-table-wrap"><table className="pilot-table"><caption>Original allocations, signed corrections and combined totals</caption><thead><tr><th scope="col">Measure</th><th scope="col">Original allocations</th><th scope="col">Signed corrections</th><th scope="col">Combined</th></tr></thead><tbody>{[...serviceComponents,['revenue_minor','Revenue subtotal'],['total_minor','Total allocation'],['occupied_nights','Occupied nights']].map(([key,label])=><tr key={key}><th scope="row">{label}</th>{[ordinary,corrections,total].map((data,i)=><td key={i}>{key==='occupied_nights'?data.occupied_nights:reportUsd(data[key as keyof ServiceTotals] as number)}</td>)}</tr>)}</tbody></table></div>}
